'use client';
import {useState,useRef} from 'react';
import Link from 'next/link';
import Image from 'next/image';
import {useRouter} from 'next/navigation';
import {MapPin,FileText,ImagePlus,Sparkles,ArrowRight,ArrowLeft,ShieldCheck,CheckCircle2,Loader2,X} from 'lucide-react';
import {DISTRICTS,CATEGORIES} from '@/lib/constants';
import {request,jsonBody} from '@/lib/client';
import {ErrorBox} from './city-ui';
export default function NewTicket({district,category}:{district:string;category:string}){const router=useRouter();const [files,setFiles]=useState<{file:File;id?:string}[]>([]);const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');const [error,setError]=useState('');const [result,setResult]=useState<any>(null);const inputRef=useRef<HTMLInputElement>(null);
 async function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();if(busy)return;setBusy(true);setError('');const form=new FormData(e.currentTarget);try{const uploadIds:string[]=[];for(let i=0;i<files.length;i++){const entry=files[i];if(entry?.id){uploadIds.push(entry.id);continue;}if(!entry?.file)continue;setMessage(`Fotoğraf yükleniyor (${i+1}/${files.length})…`);const f=entry.file;const upload=await request('/api/upload/presigned',{method:'POST',...jsonBody({fileName:f.name,contentType:f.type,size:f.size})});const put=await fetch(upload.uploadUrl,{method:'PUT',headers:{'Content-Type':f.type},body:f});if(!put.ok)throw new Error('Fotoğraf buluta yüklenemedi. Tekrar deneyin.');await request('/api/upload/complete',{method:'POST',...jsonBody({id:upload.id})});uploadIds.push(upload.id);setFiles((prev)=>prev.map((item,j)=>j===i?{...item,id:upload.id}:item));}
 setMessage('Başvurunuz inceleniyor…');const response=await fetch('/api/tickets',{method:'POST',...jsonBody({title:form.get('title'),description:form.get('description'),district:form.get('district'),neighborhood:form.get('neighborhood'),category:form.get('category'),uploadIds})});if(!response.ok){let body:any;try{body=await response.json();}catch{body={};}throw new Error(body?.error??'Başvuru gönderilemedi.');}const reader=response.body?.getReader();if(!reader)throw new Error('Yanıt akışı alınamadı.');let buffer='';const decoder=new TextDecoder();let completed=false;while(true){const chunk=await reader.read();if(chunk.done)break;buffer+=decoder.decode(chunk.value,{stream:true});const packets=buffer.split('\n\n');buffer=packets.pop()??'';for(const packet of packets){if(!packet.startsWith('data: '))continue;let data:any;try{data=JSON.parse(packet.slice(6));}catch{continue;}if(data?.status==='error')throw new Error(data?.message??'Sınıflandırma yapılamadı.');if(data?.status==='processing')setMessage(data?.message??'İşleniyor…');if(data?.status==='completed'){completed=true;setResult(data?.result);}}}if(!completed)throw new Error('Bağlantı tamamlanmadan kesildi. Tekrar göndermeden önce Başvurularım ekranını kontrol edin.');
 }catch(err){console.error(err);setError(err instanceof Error?err.message:'Başvuru tamamlanamadı.');}finally{setBusy(false);}}
 function addFiles(list:FileList|null){setError('');const selected=Array.from(list??[]);if(files.length+selected.length>3){setError('En fazla 3 fotoğraf ekleyebilirsiniz.');return;}if(selected.some((f)=>f.size>10*1024*1024||!['image/jpeg','image/png','image/webp'].includes(f.type))){setError('Fotoğraflar JPG, PNG veya WebP biçiminde, en fazla 10 MB olmalı.');return;}setFiles((prev)=>[...prev,...selected.map((file)=>({file}))]);}
 return <div className="mx-auto max-w-[960px]"><Link href="/basvurular" className="mb-5 inline-flex items-center gap-2 rounded-lg bg-card px-3 py-2 text-xs text-muted-foreground"><ArrowLeft size={14}/>Başvurulara dön</Link><h1 className="page-title">Yeni başvuru oluştur</h1><p className="mb-7 mt-2 text-sm text-muted-foreground">İhtiyacını paylaş, İstanbul için çözümün bir parçası ol.</p>{result?<section className="panel p-8 text-center"><CheckCircle2 className="mx-auto mb-5 text-chart-4" size={44}/><h2 className="text-2xl font-semibold">Başvurun alındı.</h2><p className="mt-3 text-sm text-muted-foreground">Başvurun uygulama içinde {result?.assignedDepartment} birimine yönlendirildi.</p><div className="mx-auto mt-5 max-w-md rounded-lg bg-accent p-4 text-sm"><p>Kategori: {CATEGORIES[result?.category]??'Diğer'}</p><p className="mt-2">Yapay zekâ güven tahmini: %{Math.round((result?.confidence??0)*100)}</p></div><p className="my-5 text-xs text-muted-foreground">Bu bir model tahminidir; belediye tarafından doğrulanmış değerlendirme değildir.</p><Link href={`/basvurular/${result?.id}`} className="btn">Başvurumu takip et <ArrowRight size={16}/></Link></section>:<div className="grid gap-6 lg:grid-cols-[1fr_260px]"><form onSubmit={submit} className="panel p-6"><fieldset disabled={busy} className="space-y-6"><div className="flex items-center gap-2 border-b pb-4 text-sm font-semibold"><FileText size={18} className="text-primary"/>Başvuru bilgileri</div><label className="field">Başlık <input name="title" required minLength={5} maxLength={140} placeholder="Örn. Sokağımızdaki kaldırımın onarılması"/></label><div className="grid gap-4 sm:grid-cols-2"><label className="field">İlçe<select name="district" defaultValue={district}>{DISTRICTS.map((d)=><option key={d}>{d}</option>)}</select></label><label className="field">Mahalle / sokak <span className="sr-only">isteğe bağlı</span><input name="neighborhood" maxLength={120} placeholder="Mahalle ve sokak bilgisi"/></label></div><label className="field">Hizmet kategorisi<select name="category" defaultValue={category}>{Object.entries(CATEGORIES).map(([value,label])=><option key={value} value={value}>{label}</option>)}</select><span className="text-[11px] font-normal text-muted-foreground">Yapay zekâ açıklamanıza göre bu kategoriyi güncelleyebilir.</span></label><label className="field">Açıklama<textarea name="description" required minLength={20} maxLength={5000} rows={5} placeholder="Sorunu, konumunu ve ne zamandır devam ettiğini anlatın. Kişisel veya hassas bilgi paylaşmayın."/></label><div><label className="field mb-2" htmlFor="photos">Fotoğraflar <span className="text-xs font-normal text-muted-foreground">İsteğe bağlı · En fazla 3 fotoğraf</span></label><input ref={inputRef} id="photos" type="file" accept="image/jpeg,image/png,image/webp" multiple className="sr-only" onChange={(e)=>{addFiles(e.target.files);e.target.value='';}}/><button type="button" onClick={()=>inputRef.current?.click()} className="flex w-full flex-col items-center gap-2 rounded-xl border border-dashed border-primary/30 bg-accent/40 p-6 text-primary"><ImagePlus size={27}/><span className="text-sm font-medium">Fotoğraf seçmek için tıkla</span><span className="text-[10px] text-muted-foreground">JPG, PNG veya WebP · Fotoğraf başına en fazla 10 MB</span></button>{files.map((f,i)=><div key={`${f.file.name}-${i}`} className="mt-2 flex items-center gap-2 rounded-lg bg-muted px-3 py-2 text-xs"><ImagePlus size={15}/><span className="min-w-0 flex-1 truncate">{f.file.name}</span>{f.id&&<CheckCircle2 size={14} className="text-chart-4"/>}<button type="button" onClick={()=>setFiles((prev)=>prev.filter((_,j)=>i!==j))} aria-label={`${f.file.name} fotoğrafını kaldır`} className="p-1"><X size={14}/></button></div>)}</div></fieldset><ErrorBox message={error}/>{busy&&<div role="status" className="my-4 flex items-center gap-2 rounded-lg bg-accent p-4 text-sm text-primary"><Loader2 className="animate-spin" size={18}/>{message}</div>}<p className="my-5 flex gap-2 text-[10px] leading-relaxed text-muted-foreground"><ShieldCheck size={17} className="shrink-0"/>Bilgileriniz ve fotoğraflarınız başvurunun işlenmesi için saklanır. Yalnızca siz ve yetkili yöneticiler görebilir.</p><button disabled={busy} className="btn w-full">{busy?<Loader2 size={16} className="animate-spin"/>:<Sparkles size={16}/>} {busy?'Başvuru işleniyor…':'Başvuruyu gönder'}</button></form><aside className="space-y-4"><div className="rounded-xl bg-secondary p-5 text-secondary-foreground"><Sparkles size={24} className="mb-4 text-primary"/><h2 className="text-sm font-semibold">Doğru birime, otomatik.</h2><p className="mt-3 text-xs leading-relaxed text-secondary-foreground/65">Yapay zekâ başvurunu analiz eder, hizmet kategorisini belirler ve ilgili birime yönlendirir.</p><ol className="mt-5 space-y-4 text-xs">{['Başvurunu oluştur','Akıllı yönlendirmeyi tamamla','Durumunu takip et'].map((s,i)=><li key={s} className="flex items-center gap-3"><span className="grid h-6 w-6 place-items-center rounded-full bg-secondary-foreground/10 text-[10px]">{i+1}</span>{s}</li>)}</ol></div><div className="panel p-5"><MapPin size={21} className="mb-3 text-primary"/><h2 className="text-sm font-semibold">Konum bilgisi önemli</h2><p className="mt-2 text-xs leading-relaxed text-muted-foreground">Mahalle ve sokak bilgisini eklemen, sorunun daha kolay anlaşılmasını sağlar.</p></div><p className="px-2 text-[10px] leading-relaxed text-muted-foreground">Bu platform bir MVP’dir. Başvurular gerçek belediye sistemlerine iletilmez; yönlendirme uygulama içinde yapılır. Acil durumlarda 112’yi arayın.</p></aside></div>}</div>;
}
